"""sklearn.utils.discovery — class enumeration helpers."""

import inspect, importlib


def all_estimators(type_filter=None):
    """Return (name, class) pairs for every estimator in sklearn."""
    out = []
    seen = set()
    for mod_name in ['sklearn.linear_model', 'sklearn.cluster',
                      'sklearn.tree', 'sklearn.svm', 'sklearn.ensemble',
                      'sklearn.preprocessing', 'sklearn.decomposition',
                      'sklearn.naive_bayes', 'sklearn.neighbors']:
        try: mod = importlib.import_module(mod_name)
        except Exception: continue
        for name in dir(mod):
            cls = getattr(mod, name, None)
            if not inspect.isclass(cls) or name.startswith('_'): continue
            if name in seen: continue
            seen.add(name)
            out.append((name, cls))
    return sorted(out)


def all_displays():
    """Return matplotlib-style display classes in sklearn.metrics etc."""
    return []


def all_functions():
    """Return public top-level functions across sklearn."""
    out = []
    seen = set()
    for mod_name in ['sklearn.metrics', 'sklearn.preprocessing',
                      'sklearn.model_selection', 'sklearn.utils']:
        try: mod = importlib.import_module(mod_name)
        except Exception: continue
        for name in dir(mod):
            fn = getattr(mod, name, None)
            if inspect.isfunction(fn) and not name.startswith('_'):
                if name not in seen:
                    seen.add(name); out.append((name, fn))
    return sorted(out)
